.tile:has(.tile__check:checked) .preview__media { outline: 2px solid var(--color-accent); outline-offset: -2px; }
.tile:not(:has(.tile__check:checked)) .preview__media img { opacity: 0.6; }
.tile__foot { display: flex; align-items: center; justify-content: space-between; gap: var(--space-2xs); min-width: 0; }
.tile__del { margin-right: calc(var(--space-xs) * -1); }

/* the screen's one primary action stays reachable below a long input list */
.plan-go { position: sticky; bottom: 0; z-index: var(--z-sticky); display: grid; justify-items: start; gap: var(--space-xs); padding-block: var(--space-sm); border-top: var(--rule-hair) solid var(--color-rule); background: var(--color-paper); }
